// Generated by scripts/build.mjs. Edit the source modules, not this file.
// Shared by the static build and progressive enhancement in the browser.
export const DEVELOPER_ID = 1858655640;
export const APPLE_LOOKUP = `https://itunes.apple.com/lookup?id=${DEVELOPER_ID}&entity=software&country=us&limit=200`;

export function escapeHTML(value = '') {
  return String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

export function safeURL(value, allowedHosts = []) {
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:' || url.username || url.password) return '';
    if (allowedHosts.length && !allowedHosts.some(host => url.hostname === host || url.hostname.endsWith(`.${host}`))) return '';
    return url.href;
  } catch { return ''; }
}

export function normalizeApps(response, knownApps = []) {
  if (!Array.isArray(response?.results)) throw new Error('Invalid App Store response');
  const known = new Map(knownApps.map(app => [app.id, app]));
  const unique = new Map();
  for (const app of response.results) {
    if (app.wrapperType !== 'software' || Number(app.artistId) !== DEVELOPER_ID || !Number.isSafeInteger(app.trackId) || !app.trackName) continue;
    const url = safeURL(app.trackViewUrl, ['apps.apple.com']);
    const icon = safeURL(app.artworkUrl512 || app.artworkUrl100, ['mzstatic.com']);
    if (!url || !icon) continue;
    const previous = known.get(app.trackId);
    unique.set(app.trackId, {
      id: app.trackId, name: app.trackName, genre: app.primaryGenreName || 'App', icon, url,
      description: previous?.description || String(app.description || '').split(/\n/)[0].slice(0, 240),
      rating: Number.isFinite(Number(app.averageUserRating)) ? Math.min(5, Math.max(0, Number(app.averageUserRating))) : 0,
      count: Number.isFinite(Number(app.userRatingCount)) ? Math.max(0, Math.floor(Number(app.userRatingCount))) : 0,
      released: String(app.releaseDate || '').slice(0, 10),
      updated: String(app.currentVersionReleaseDate || '').slice(0, 10)
    });
  }
  if (!unique.size) throw new Error('No verified developer apps returned');
  return [...unique.values()];
}

export function sortApps(apps, order = 'popular') {
  const recent = (a, b) => (b.released || '').localeCompare(a.released || '') || a.name.localeCompare(b.name);
  return [...apps].sort((a, b) => order === 'newest' ? recent(a, b)
    : order === 'rating' ? Number(b.count > 0) - Number(a.count > 0) || b.rating - a.rating || b.count - a.count || recent(a, b)
    : b.count - a.count || recent(a, b));
}

export function filterRecords(records, query = '', category = 'all') {
  const words = query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
  return records.filter(item => (category === 'all' || item.category === category)
    && words.every(word => `${item.name} ${item.description} ${item.genre || item.category || ''}`.toLocaleLowerCase().includes(word)));
}

export const arrow = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14" stroke="currentColor" stroke-width="1.5"/></svg>';

export function renderProject(project, index) {
  const url = safeURL(project.url);
  if (!url) throw new Error(`Invalid project URL: ${project.id}`);
  const status = project.status === 'Live' ? '' : `<span class="project-status">${escapeHTML(project.status)}</span>`;
  return `<article class="project-card" data-category="${escapeHTML(project.category)}" data-project="${escapeHTML(project.id)}">
    <a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer" class="project-link">
      <div class="project-top"><span class="project-monogram" aria-hidden="true">${escapeHTML(project.monogram)}</span><span class="project-category">${escapeHTML(project.category)}</span>${arrow}</div>
      <h3>${escapeHTML(project.name)}</h3><p>${escapeHTML(project.description)}</p>
      <div class="project-bottom"><span class="project-domain">${escapeHTML(new URL(url).hostname.replace(/^www\./, ''))}</span>${status}<span class="sr-only"> (opens in a new tab)</span></div>
    </a>
  </article>`;
}

export function renderApp(app, index) {
  const url = safeURL(app.url, ['apps.apple.com']);
  const icon = safeURL(app.icon, ['mzstatic.com']);
  if (!url || !icon) throw new Error(`Invalid app URL: ${app.id}`);
  const rating = app.count > 0
    ? `<span class="app-rating"><span aria-hidden="true">★</span> ${app.rating.toFixed(1)} <span class="sr-only">out of 5,</span><span class="rating-count">${app.count.toLocaleString('en-US')} ${app.count === 1 ? 'rating' : 'ratings'}</span></span>`
    : '<span class="app-unrated">Not yet rated</span>';
  return `<article class="app-card" data-app-id="${app.id}">
    <a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">
      <div class="app-top"><img src="${escapeHTML(icon)}" width="56" height="56" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer"><span class="app-number" aria-hidden="true">${String(index + 1).padStart(2, '0')}</span>${arrow}</div>
      <h3>${escapeHTML(app.name)}</h3><span class="app-genre">${escapeHTML(app.genre)}</span><p>${escapeHTML(app.description)}</p>
      <div class="app-bottom">${rating}<span class="sr-only"> · View on the App Store (opens in a new tab)</span></div>
    </a>
  </article>`;
}

// An original, deterministic spiral galaxy. Native scrolling moves the camera;
// the page never captures or replaces wheel/touch scrolling.
const vertexSource = `
attribute vec3 aPosition;
attribute vec3 aColor;
attribute float aSize;
uniform float uTime;
uniform float uProgress;
uniform float uAspect;
uniform float uDpr;
uniform float uMobile;
uniform vec2 uPointer;
varying vec3 vColor;
varying float vOpacity;
void main() {
  vec3 p = aPosition;
  float starField = step(20.0, aSize);
  float rotation = uTime * 0.012 + uProgress * 0.42;
  float ca = cos(rotation), sa = sin(rotation);
  p.xy = mat2(ca, -sa, sa, ca) * p.xy;
  float tilt = 1.01 - uProgress * 0.68 + uPointer.y * 0.035;
  p.yz = mat2(cos(tilt), -sin(tilt), sin(tilt), cos(tilt)) * p.yz;
  float roll = -0.40 + uProgress * 0.18 + uPointer.x * 0.025;
  p.xy = mat2(cos(roll), -sin(roll), sin(roll), cos(roll)) * p.xy;
  float depth = 10.5 + p.z;
  float scale = mix(1.74, 1.25, uMobile) + uProgress * 0.10;
  vec2 center = vec2(mix(0.43, 0.24, uMobile) - uProgress * 0.34, mix(0.04, -0.40, uMobile) + uProgress * 0.15);
  vec2 xy = (p.xy * scale / depth) / vec2(uAspect, 1.0) + center;
  xy += uPointer * vec2(0.010, 0.007);
  if (starField > 0.5) {
    xy = aPosition.xy + uPointer * 0.004;
    gl_PointSize = (aSize - 20.0) * uDpr;
    vOpacity = 0.34 + aPosition.z * 0.05;
  } else {
    gl_PointSize = clamp(aSize * uDpr * (10.0 / depth), 0.65, 22.0 * uDpr);
    vOpacity = mix(0.56, 0.35, smoothstep(3.5, 6.4, length(aPosition.xy))) * min(1.0, 1.5 / aSize);
  }
  gl_Position = vec4(xy, 0.5, 1.0);
  vColor = aColor;
}`;

const fragmentSource = `
precision mediump float;
varying vec3 vColor;
varying float vOpacity;
void main() {
  vec2 point = gl_PointCoord * 2.0 - 1.0;
  float radius = dot(point, point);
  if (radius > 1.0) discard;
  float light = exp(-radius * 4.0) * (1.0 - smoothstep(0.48, 1.0, radius));
  gl_FragColor = vec4(vColor * light * vOpacity, light * vOpacity);
}`;

export function createGalaxy(canvas, { reducedMotion = false, paused = false } = {}) {
  let gl;
  try { gl = canvas.getContext('webgl', { alpha: true, antialias: false, depth: false, stencil: false, premultipliedAlpha: true, powerPreference: 'low-power' }); } catch { return null; }
  if (!gl) return null;
  const compile = (type, source) => {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source); gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) { gl.deleteShader(shader); throw new Error('Galaxy shader unavailable'); }
    return shader;
  };
  let program, vertex, fragment;
  try {
    vertex = compile(gl.VERTEX_SHADER, vertexSource); fragment = compile(gl.FRAGMENT_SHADER, fragmentSource);
    program = gl.createProgram(); gl.attachShader(program, vertex); gl.attachShader(program, fragment); gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error('Galaxy unavailable');
  } catch { return null; }
  gl.deleteShader(vertex); gl.deleteShader(fragment);
  gl.useProgram(program);
  let seed = 20260319;
  const random = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  const normal = () => Math.sqrt(-2 * Math.log(Math.max(0.00001, random()))) * Math.cos(2 * Math.PI * random());
  const mobileInitially = innerWidth < 720;
  const lowPower = navigator.connection?.saveData || (navigator.hardwareConcurrency && navigator.hardwareConcurrency < 4);
  const count = lowPower ? 16000 : mobileInitially ? 28000 : 65000;
  const fieldCount = mobileInitially ? 190 : 390;
  const data = new Float32Array((count + fieldCount) * 7);
  for (let i = 0; i < count; i++) {
    const core = random() < 0.26;
    const r = core ? Math.sqrt(-Math.log(Math.max(.00001, random()))) * .63 : 0.16 + Math.pow(random(), 0.70) * 6.05;
    const arm = Math.floor(random() * 2) * Math.PI;
    const scatter = random() < 0.45;
    const theta = core || scatter ? random() * Math.PI * 2 : arm + r * 1.13 + normal() * (0.16 + 0.11 / (r + 0.4));
    const width = core ? .29 : .065 + .09 * Math.exp(-r);
    const x = Math.cos(theta) * r, y = Math.sin(theta) * r, z = normal() * width;
    const outward = Math.min(1, r / 3.0);
    const special = random() < .018;
    const color = special ? [0.64, 0.76, 1] : [1 - outward * .60, .76 - outward * .17, .46 + outward * .45];
    const brightness = .75 + random() * .65;
    // Mostly pinprick stars; a few soft, larger points supply an optical glow.
    const size = special ? 2.5 + random() * 3.5 : core && random() < .015 ? 8 + random() * 8 : .7 + Math.pow(random(), 4) * 2.5;
    data.set([x, y, z, color[0] * brightness, color[1] * brightness, color[2] * brightness, size], i * 7);
  }
  for (let i = 0; i < fieldCount; i++) data.set([random() * 2 - 1, random() * 2 - 1, random(), .64, .74, .88, 20.6 + random() * 1.8], (count + i) * 7);
  const buffer = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, buffer); gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
  for (const [name, size, offset] of [['aPosition', 3, 0], ['aColor', 3, 12], ['aSize', 1, 24]]) {
    const attribute = gl.getAttribLocation(program, name); gl.enableVertexAttribArray(attribute); gl.vertexAttribPointer(attribute, size, gl.FLOAT, false, 28, offset);
  }
  const uniforms = Object.fromEntries(['uTime', 'uProgress', 'uAspect', 'uDpr', 'uMobile', 'uPointer'].map(key => [key, gl.getUniformLocation(program, key)]));
  gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE); gl.disable(gl.DEPTH_TEST); gl.clearColor(0, 0, 0, 0);
  let frame = 0, time = 0, last = 0, lastDraw = 0, progress = 0, targetProgress = 0, visible = true, lost = false;
  let pointer = [0, 0], targetPointer = [0, 0];
  const state = { paused, reducedMotion };
  const active = () => !state.paused && !state.reducedMotion && visible && !document.hidden && !lost;
  let width = 0, height = 0, dpr = 1;
  function draw() {
    if (lost) return;
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform1f(uniforms.uTime, time); gl.uniform1f(uniforms.uProgress, progress); gl.uniform1f(uniforms.uAspect, width / height);
    gl.uniform1f(uniforms.uDpr, dpr); gl.uniform1f(uniforms.uMobile, width < 720 ? 1 : 0); gl.uniform2f(uniforms.uPointer, pointer[0], pointer[1]);
    gl.drawArrays(gl.POINTS, 0, count + fieldCount);
  }
  function tick(now) {
    frame = 0;
    if (!active()) { last = 0; return; }
    // Limit the decorative scene to 30fps; native scroll and page input remain independent.
    if (now - lastDraw >= 31) {
      time += last ? Math.min((now - last) / 1000, .05) : 0;
      last = now; lastDraw = now;
      progress += (targetProgress - progress) * .075;
      pointer = pointer.map((value, index) => value + (targetPointer[index] - value) * .025);
      draw();
    }
    frame = requestAnimationFrame(tick);
  }
  function start() { if (!frame && active()) frame = requestAnimationFrame(tick); }
  function stop() { cancelAnimationFrame(frame); frame = 0; last = 0; }
  function resize() {
    width = innerWidth; height = innerHeight;
    dpr = Math.min(devicePixelRatio || 1, width < 720 || lowPower ? 1.25 : 1.5);
    canvas.width = Math.round(width * dpr); canvas.height = Math.round(height * dpr);
    gl.viewport(0, 0, canvas.width, canvas.height); draw();
  }
  function visibility() { if (active()) start(); else stop(); }
  function contextLost(event) { event.preventDefault(); lost = true; stop(); canvas.parentElement.classList.remove('ready'); }
  const onResize = () => { resize(); start(); };
  window.addEventListener('resize', onResize, { passive: true });
  document.addEventListener('visibilitychange', visibility);
  canvas.addEventListener('webglcontextlost', contextLost);
  resize(); canvas.parentElement.classList.add('ready'); start();
  return {
    update(scroll) {
      targetProgress = Math.min(1, Math.max(0, scroll / Math.max(1, innerHeight * 1.35)));
      visible = scroll < innerHeight * 2.5;
      if (active()) start(); else stop();
    },
    pointer(x, y) { if (active()) targetPointer = [x, y]; },
    setMotion(next) { Object.assign(state, next); if (active()) start(); else { stop(); pointer = [0, 0]; draw(); } },
    destroy() { stop(); window.removeEventListener('resize', onResize); document.removeEventListener('visibilitychange', visibility); canvas.removeEventListener('webglcontextlost', contextLost); gl.deleteBuffer(buffer); gl.deleteProgram(program); }
  };
}


document.documentElement.classList.add('js');
const $ = selector => document.querySelector(selector);
const snapshot = JSON.parse($('#app-snapshot').textContent);
const web = JSON.parse($('#project-snapshot').textContent);
let apps = snapshot.apps;
let category = 'all';
let appInteracted = false;
let pendingApps = null;

function markFreshApps() {
  $('[data-app-count]').innerHTML = `${apps.length}<span>↗</span>`;
  $('[data-app-total]').textContent = apps.length;
  $('#app-source').textContent = `Live U.S. App Store ratings · ${new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}. Ratings are not download counts.`;
}

// Controls only appear after their static fallbacks are ready.
document.querySelectorAll('[data-enhanced]').forEach(element => { element.hidden = false; });
function updateProjects() {
  const projects = filterRecords(web.projects, $('#project-search').value, category);
  $('#project-grid').innerHTML = projects.map(renderProject).join('');
  $('#project-results').textContent = `${projects.length} of ${web.projects.length} projects`;
  $('#project-empty').hidden = projects.length > 0;
}
document.querySelectorAll('.filters button').forEach(button => button.addEventListener('click', () => {
  category = button.dataset.category;
  document.querySelectorAll('.filters button').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
  updateProjects();
}));
$('#project-search').addEventListener('input', updateProjects);

function updateApps() {
  if (pendingApps) { apps = pendingApps; pendingApps = null; markFreshApps(); }
  const order = $('#app-sort').value;
  const filtered = sortApps(filterRecords(apps, $('#app-search').value), order);
  $('#app-grid').innerHTML = filtered.map(renderApp).join('');
  $('#app-results').textContent = `${filtered.length} of ${apps.length} apps`;
  $('#app-empty').hidden = filtered.length > 0;
  $('#ranking-note').textContent = order === 'newest' ? 'Ordered by original U.S. App Store release date, newest first.' : order === 'rating' ? 'Ordered by average U.S. App Store rating. Unrated apps appear last.' : 'Popularity = number of U.S. App Store ratings. Ties show newer releases first.';
}
for (const [selector, event] of [['#app-sort', 'change'], ['#app-search', 'input']]) $(selector).addEventListener(event, () => { appInteracted = true; updateApps(); });

// Best-effort refresh. A complete, indexable snapshot is already in the HTML.
// Never remove saved apps because of a partial/region-specific Apple response.
async function refreshApps() {
  try {
    const response = await fetch(APPLE_LOOKUP, { signal: AbortSignal.timeout(6500), credentials: 'omit', referrerPolicy: 'no-referrer' });
    if (!response.ok) throw new Error('App Store unavailable');
    const fresh = normalizeApps(await response.json(), snapshot.apps);
    const freshIds = new Set(fresh.map(app => app.id));
    if (snapshot.apps.some(app => !freshIds.has(app.id))) throw new Error('App Store snapshot incomplete');
    // Do not move cards beneath someone already exploring the collection.
    const inUse = appInteracted || $('#app-grid').contains(document.activeElement) || $('#apps').getBoundingClientRect().top < innerHeight;
    if (inUse) { pendingApps = fresh; return; }
    apps = fresh; updateApps();
    markFreshApps();
  } catch { /* The dated, verified snapshot stays visible. No empty/error-only page. */ }
}
refreshApps();

const menu = $('.menu-toggle');
const nav = $('#main-nav');
menu.hidden = false;
function setMenu(open, returnFocus = false) {
  menu.setAttribute('aria-expanded', String(open)); nav.classList.toggle('is-open', open); document.body.classList.toggle('menu-open', open);
  document.querySelectorAll('main, .site-footer, .scene-control').forEach(element => { element.inert = open; });
  if (returnFocus) menu.focus();
}
menu.addEventListener('click', () => setMenu(menu.getAttribute('aria-expanded') !== 'true'));
nav.addEventListener('click', event => { if (event.target.closest('a')) setMenu(false); });
document.addEventListener('keydown', event => {
  if (menu.getAttribute('aria-expanded') !== 'true') return;
  if (event.key === 'Escape') { setMenu(false, true); return; }
  if (event.key === 'Tab') {
    const links = [...nav.querySelectorAll('a')];
    if (event.shiftKey && document.activeElement === menu) { event.preventDefault(); links.at(-1).focus(); }
    else if (!event.shiftKey && document.activeElement === links.at(-1)) { event.preventDefault(); menu.focus(); }
  }
});
matchMedia('(min-width: 721px)').addEventListener('change', event => { if (event.matches) setMenu(false); });

const motionPreference = matchMedia('(prefers-reduced-motion: reduce)');
let paused = motionPreference.matches;
try { paused ||= localStorage.getItem('andromeda.motion') === 'paused'; } catch { /* Storage may be blocked. */ }
let galaxy = null;
try { galaxy = createGalaxy($('#galaxy'), { reducedMotion: motionPreference.matches, paused }); } catch { /* Static galaxy remains. */ }
const motionButtons = [$('#motion-toggle'), $('#scene-toggle')];
function syncMotion() {
  document.body.classList.toggle('motion-paused', paused);
  document.documentElement.classList.toggle('motion-paused', paused);
  for (const button of motionButtons) {
    button.hidden = !galaxy;
    button.setAttribute('aria-pressed', String(paused));
    button.setAttribute('aria-label', paused ? 'Resume galaxy animation' : 'Pause galaxy animation');
  }
  $('#motion-toggle').innerHTML = paused ? 'Resume motion <span aria-hidden="true">▷</span>' : 'Pause motion <span aria-hidden="true">Ⅱ</span>';
  $('.scene-control-icon').textContent = paused ? '▷' : 'Ⅱ';
  $('.scene-control-text').textContent = paused ? 'Resume motion' : 'Pause motion';
  galaxy?.setMotion({ paused, reducedMotion: motionPreference.matches && paused });
}
motionButtons.forEach(button => button.addEventListener('click', () => {
  paused = !paused;
  try { localStorage.setItem('andromeda.motion', paused ? 'paused' : 'playing'); } catch { /* Preference is optional. */ }
  syncMotion();
}));
motionPreference.addEventListener('change', event => { paused = event.matches; syncMotion(); });
syncMotion();

let scrollFrame = 0;
function onScroll() {
  scrollFrame = 0;
  const y = scrollY;
  $('.site-header').classList.toggle('is-scrolled', y > 72);
  const height = Math.max(1, document.documentElement.scrollHeight - innerHeight);
  document.documentElement.style.setProperty('--reading-progress', String(Math.min(1, y / height)));
  document.documentElement.style.setProperty('--universe-opacity', String(Math.max(.08, 1 - y / (innerHeight * 1.75))));
  $('#scene-toggle').classList.toggle('at-content', y > innerHeight * 1.5);
  galaxy?.update(y);
}
window.addEventListener('scroll', () => { if (!scrollFrame) scrollFrame = requestAnimationFrame(onScroll); }, { passive: true });
window.addEventListener('resize', onScroll, { passive: true });
if (matchMedia('(pointer: fine)').matches) window.addEventListener('pointermove', event => { galaxy?.pointer((event.clientX / innerWidth - .5) * 2, (.5 - event.clientY / innerHeight) * 2); }, { passive: true });
window.addEventListener('pagehide', () => galaxy?.setMotion({ paused: true }));
window.addEventListener('pageshow', () => { syncMotion(); onScroll(); });
onScroll();
